/**
 * A Son Named Methuselah
 * ----------------------
 * Enoch fathers Methuselah and a home is prepared for the child. Stage: a small house at sunrise, a newborn in swaddling cloth, the father at the door; a lamp lit in the window, a warm quiet room.
 *
 * Palette 0x2a1a10 → 0x060402 · light: ember · hero: house
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./enoch-kit.js.
 */

import { THREE, createScene, house, person } from './enoch-kit.js';

const BG = 0x2a1a10;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 1575954335, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 16, 0, -17, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the house */
    house(W, group, 0, 0, -2, 1.3, { mud: 0x060402 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2a1a10, ry: -0.15, s: 1.01 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, ry: 0.01, s: 1.04 });

    return W.finish();
}

export default { build };
